"""Correction executor: dispatch + replay drivers for cross-phase corrections.

Owns the *apply + replay* half of the mechanism (the discovery half lives in
:mod:`.discovery`). Extracted from ``SkillExecutor`` so all correction logic
lives together; it depends on a few executor collaborators (the tool registry, a
tool-invoke callable, and the active-collect-step resolver), injected at
construction to avoid a back-reference to ``SkillExecutor``.
"""

from __future__ import annotations

from typing import (
    TYPE_CHECKING,
    Any,
    Awaitable,
    Callable,
    Dict,
    List,
    Mapping,
    Optional,
    Tuple,
)

import structlog

from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
    UserFlowStackFrame,
)
from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.orchestration.correction.coercion import (
    coerce_to_field_type,
    reinvoke_arguments,
)
from rasa.mantle.orchestration.correction.discovery import (
    find_correctable_fields,
    is_autonomous_skill,
)
from rasa.mantle.orchestration.correction.models import CorrectableMemoryItem
from rasa.mantle.orchestration.correction.replay import (
    build_rewound_stack,
    reconstruct_stack_for_reentry,
    slots_to_clear_after_rewind,
)
from rasa.mantle.orchestration.memory_validation_tools import is_memory_validation_tool
from rasa.mantle.orchestration.settable_write import write_settable_field
from rasa.mantle.skills.stack_frame_helpers import catalog_step_id, target_id_for_frame
from rasa.mantle.state.provenance import (
    WriteProvenance,
    latest_provenance_for_slot,
    provenance_for_slot_by_frame,
)
from rasa.mantle.state.repair_metadata import CorrectionMetadata
from rasa.shared.core.events import (
    Event,
    MemoryCleared,
    create_memory_write_event,
    is_memory_write_event,
)

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.frames.dialogue_stack_frame import (
        DialogueStackFrame,
    )
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.mantle.skills.steps import CollectStep
    from rasa.mantle.state.tracker_handle import TrackerHandle
    from rasa.mantle.tools.mcp_runtime import MCPRuntime

structlogger = structlog.get_logger()

# Signature of the executor's registered-tool invoker
# (``SkillExecutor.call_tool_func``).
CallToolFunc = Callable[
    [
        Optional[Callable[..., Any]],
        str,
        Dict[str, Any],
        "TrackerHandle",
        Optional[Tuple[str, str]],
    ],
    Awaitable[str],
]
# Signature of the active-collect-step resolver
# (``SkillExecutor.active_collect_step``).
ActiveCollectStep = Callable[["TrackerHandle"], Optional["CollectStep"]]


def _button_key_written_this_turn() -> Optional[str]:
    """Return the memory key a ``set:`` tap stored on this turn, if any.

    The key lives on the incoming turn, not on the write event, so discovery
    cannot see it from the tracker alone. Outside a turn there is nothing to
    exclude.
    """
    try:
        # Local import: turn context pulls the prompt stack, which imports this
        # package while it is still loading.
        from rasa.mantle.orchestration.turn_context import current_turn_context

        key = current_turn_context().turn.set_memory_button_written_key
    except LookupError:
        return None
    return key or None


def _correction_trigger_ids(
    frame: UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame,
) -> Tuple[str, str]:
    """Return activation unit id and catalog step id for correction metadata."""
    return target_id_for_frame(frame), catalog_step_id(frame)


class CorrectionExecutor:
    """Applies ``correct()`` tool calls and drives the post-correction replay."""

    def __init__(
        self,
        skill_catalog: "SkillCatalog",
        tool_funcs: Mapping[str, Mapping[str, Callable[..., Any]]],
        call_tool_func: CallToolFunc,
        active_collect_step: ActiveCollectStep,
        mcp_runtime: Optional["MCPRuntime"] = None,
    ) -> None:
        self._skill_catalog = skill_catalog
        self._tool_funcs = tool_funcs
        self._call_tool_func = call_tool_func
        self._active_collect_step = active_collect_step
        self._mcp_runtime = mcp_runtime

    def find_correctable_memory_items(
        self, tracker_handle: "TrackerHandle"
    ) -> List[CorrectableMemoryItem]:
        """Return the memory items eligible for cross-phase correction this turn.

        Binds :func:`~rasa.mantle.orchestration.correction.find_correctable_fields`
        to this executor's catalog and the active collect step, so the
        orchestrator can build the per-turn ``correct`` tool schema from the same
        source the dispatcher validates against.
        """
        return find_correctable_fields(
            tracker_handle,
            self._skill_catalog,
            active_collect_step=self._active_collect_step(tracker_handle),
            excluded_memory_key=_button_key_written_this_turn(),
        )

    async def dispatch(
        self,
        tool_args: Dict[str, Any],
        tracker_handle: "TrackerHandle",
    ) -> str:
        """Handle a ``correct(memory_key, value)`` tool call.

        Applies a revision to a previously-provided value:

        * Validates that *memory_key* is currently correctable (else surfaces why).
        * Coerces the new value to the field's declared type.
        * If the value was produced by a builder tool (per write-provenance),
          **re-invokes that producer** with the changed argument so the tool's
          own validation runs — a rejecting producer leaves the old value in
          place (validate-before-write) and its error is surfaced to the LLM.
        * Otherwise (collect-owned / no producer) writes the corrected value
          directly through the schema-scoped memory path.

        This is the shared *apply* step. Variant-specific replay (rewind, clear,
        re-confirm, autonomy hand-back) is layered on top by the replay drivers
        and is not performed here.
        """
        memory_key = str(tool_args.get("memory_key", ""))
        if "value" not in tool_args:
            return "correct() requires both a 'memory_key' and a 'value'."
        new_value = tool_args.get("value")

        correctable = self.find_correctable_memory_items(tracker_handle)
        target = next(
            (item for item in correctable if item.memory_key == memory_key), None
        )
        if target is None:
            correctable_names = (
                ", ".join(item.memory_key for item in correctable) or "none"
            )
            structlogger.warning(
                "mantle.skill_executor.dispatch.correct.not_correctable",
                memory_key=memory_key,
            )
            return (
                f"Cannot correct '{memory_key}': it is not a correctable memory item "
                f"right now. Correctable memory items: {correctable_names}."
            )

        structlogger.debug(
            "mantle.skill_executor.dispatch.correct.target",
            field=target.memory_key,
            requires_reentry=target.requires_reentry,
            frame_id=target.frame_id,
            step_id=target.step_id,
        )

        coerced_value = coerce_to_field_type(new_value, target.field)

        # A correction that matches the stored value is a no-op — e.g. the user
        # says "actually Sapphire" when the card is already Sapphire, or the LLM
        # picks the current value by mistake. Skip both apply and replay (nothing
        # to rewind) and tell the LLM the value already stands.
        previous_value = self._current_memory_value(target, tracker_handle)
        if previous_value == coerced_value:
            structlogger.debug(
                "mantle.skill_executor.dispatch.correct.noop",
                field=target.memory_key,
            )
            return (
                f"'{target.entry_name}' is already set to {coerced_value!r}; "
                "no correction needed."
            )

        # Anchor the rewind at where the original value was produced — captured
        # before applying so the re-invoke's own (later) write does not move it.
        # For a cross-skill re-entry the value was produced by the (now completed)
        # sub-skill frame; a still-live ancestor may have re-stamped the same slot
        # later, so anchor on and re-invoke the sub-skill's *own* original write
        # rather than the latest one (which would place the anchor too late and
        # pick the wrong producer).
        original = None
        if target.requires_reentry:
            original = provenance_for_slot_by_frame(
                tracker_handle.tracker.events, target.memory_key, target.frame_id
            )
        if original is None:
            original = latest_provenance_for_slot(
                tracker_handle.tracker.events, target.memory_key
            )
        anchor_position = original.position if original is not None else None

        # Boundary into the event log so we can tell which slots the apply step
        # (re-invoking the producer) just wrote — those must survive the
        # post-rewind clearing even though they land after the anchor.
        apply_boundary = len(tracker_handle.tracker.events)
        # Stamp correction metadata from the active frame when present.
        # ``recording_correction`` only tags if the apply actually changed memory.
        trigger_frame = tracker_handle.active_frame
        if isinstance(
            trigger_frame,
            (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
        ):
            flow_id, step_id = _correction_trigger_ids(trigger_frame)
            correction = CorrectionMetadata(
                flow_id=flow_id,
                step_id=step_id,
                skill_id=trigger_frame.skill_id,
            )
            with tracker_handle.recording_correction(
                memory_key=target.memory_key, correction=correction
            ):
                result = await self._apply_correction(
                    target, coerced_value, original, tracker_handle
                )
        else:
            result = await self._apply_correction(
                target, coerced_value, original, tracker_handle
            )

        # Drive replay only when the apply actually changed the stored value.
        # A producer that rejected the new value (validate-before-write) leaves
        # the old state unchanged, so there is nothing to rewind — surface its
        # error untouched. Compare against the *previous* value rather than the
        # requested one so a producer that normalizes the input (e.g. casing or
        # whitespace) still counts as a change and triggers replay.
        if self._current_memory_value(target, tracker_handle) == previous_value:
            return result

        # Where the flow was when the user made the correction. The re-walk must
        # return here before the "correction in progress" prompt notice clears
        # (the producer re-invoke above never changes the stack, so the active
        # frame still reflects the correction point).
        resume_point = (
            (trigger_frame.frame_id, _correction_trigger_ids(trigger_frame)[1])
            if isinstance(
                trigger_frame,
                (UserFlowStackFrame, SkillStackFrame, OrderedBlockStackFrame),
            )
            else None
        )

        # Slots the apply step (re-invoking the producer) just wrote — they land
        # after the anchor but are the corrected producer's fresh output (e.g.
        # a re-derived summary/confirmation), so they must survive the post-rewind
        # clearing on *both* replay paths, not only re-entry.
        written_by_apply = {
            event.key
            for event in list(tracker_handle.tracker.events)[apply_boundary:]
            if is_memory_write_event(event)
        }

        if target.requires_reentry:
            self._replay_reentry(
                target, anchor_position, written_by_apply, tracker_handle, resume_point
            )
        else:
            self._replay_after_correction(
                target, anchor_position, written_by_apply, tracker_handle, resume_point
            )
        return result

    @staticmethod
    def _current_memory_value(
        target: CorrectableMemoryItem, tracker_handle: "TrackerHandle"
    ) -> Any:
        """Read a correctable memory item's current value via the memory manager.

        Correction always goes through the memory manager rather than reading the
        raw tracker slot, so the memory-item abstraction (scoping, resolution)
        stays the single source of truth. A denied or unset read yields ``None``.
        """
        entry = tracker_handle.memory.get(
            target.skill_id, target.flow_id, target.entry_name
        )
        return entry.value if entry is not None else None

    async def _apply_correction(
        self,
        target: CorrectableMemoryItem,
        coerced_value: Any,
        provenance: Optional[WriteProvenance],
        tracker_handle: "TrackerHandle",
    ) -> str:
        """Apply the corrected value: re-invoke the producer, else set directly.

        If the value was produced by a builder tool, re-invokes that producer
        with the changed argument so the tool's own validation runs (a rejecting
        producer keeps the old value). If that tool is no longer registered the
        correction is refused rather than written unvalidated. Values not produced
        by a tool (collect-owned) are written through the schema-scoped memory
        path. Returns the LLM-facing result string.
        """
        if provenance is not None and provenance.produced_by_tool:
            # Memory validation tools stamp provenance when they rewrite the field
            # (e.g. canonicalising a label). They only accept ``context`` — never
            # re-invoke them with the corrected value as a kwarg. Apply via the
            # settable-write path so the value is written and the tool re-runs
            # with empty args, as on the original ``set_fields`` write.
            if is_memory_validation_tool(provenance.tool):
                write_result = await write_settable_field(
                    tracker_handle,
                    target.skill_id,
                    target.flow_id,
                    target.entry_name,
                    coerced_value,
                    self._tool_funcs,
                    self._call_tool_func,
                )
                if write_result.ok:
                    return f"Corrected {target.entry_name} to {coerced_value!r}."
                reason = write_result.error or "write rejected"
                return f"Could not correct '{target.memory_key}': {reason}"

            producer = self._tool_funcs.get(target.skill_id, {}).get(provenance.tool)
            is_mcp = bool(
                self._mcp_runtime is not None
                and self._mcp_runtime.has_mcp_tool(target.skill_id, provenance.tool)
            )
            if producer is None and not is_mcp:
                # The value was produced by a builder tool, but that tool is not
                # registered for this skill (inconsistent model state). Writing
                # the value directly would bypass the producer's
                # validate-before-write rules and could persist a value the tool
                # would have rejected, so refuse the correction rather than apply
                # it unvalidated.
                structlogger.warning(
                    "mantle.skill_executor.dispatch.correct.producer_missing",
                    field=target.memory_key,
                    producer=provenance.tool,
                    skill_id=target.skill_id,
                )
                return (
                    f"Cannot correct '{target.memory_key}': the tool that "
                    f"produced it ({provenance.tool}) is unavailable, so the "
                    "change can't be validated."
                )
            new_args = reinvoke_arguments(
                provenance.arguments, target.entry_name, coerced_value
            )
            structlogger.debug(
                "mantle.skill_executor.dispatch.correct.reinvoke",
                field=target.memory_key,
                producer=provenance.tool,
            )
            return await self._call_tool_func(
                producer,
                provenance.tool,
                new_args,
                tracker_handle,
                (target.skill_id, target.flow_id),
            )

        # Collect-owned or engine direct-write (``tool=None``) — write the
        # corrected value directly, then run an optional memory validation tool.
        write_result = await write_settable_field(
            tracker_handle,
            target.skill_id,
            target.flow_id,
            target.entry_name,
            coerced_value,
            self._tool_funcs,
            self._call_tool_func,
        )
        if write_result.ok:
            return f"Corrected {target.entry_name} to {coerced_value!r}."

        reason = write_result.error or "write rejected"
        if write_result.memory_validation_failed:
            structlogger.warning(
                "mantle.skill_executor.dispatch.correct.memory_validation_failed",
                field=target.memory_key,
                reason=reason,
            )
            return (
                f"Correction rejected: memory validation tool failed for "
                f"{target.entry_name}: {reason}"
            )

        structlogger.warning(
            "mantle.skill_executor.dispatch.correct.denied",
            field=target.memory_key,
            reason=reason,
        )
        return reason

    def clear_note_if_caught_up(
        self, tracker_handle: "TrackerHandle", frame: "DialogueStackFrame"
    ) -> None:
        """Drop the post-correction re-walk notice once the flow catches up.

        A correction records the step the user was on when they revised a value
        (:meth:`TrackerHandle.set_correction_resume_point`). The prompt notice
        that warns the LLM about cleared memory stays until the re-walk returns
        to that step — or until the owning frame completes and leaves the stack,
        since a corrected value can reroute the flow so the exact step is never
        revisited. Called at the top of every ``advance_steps`` iteration so the
        marker clears the moment the flow reaches the trigger step again.
        """
        resume = tracker_handle.correction_resume_point
        if resume is None:
            return
        resume_frame_id = resume.get("frame_id")
        resume_step_id = resume.get("step_id")
        if resume_frame_id is None or resume_step_id is None:
            # Malformed / legacy resume marker (corrupted tracker, manual edit).
            # Clear it rather than raising a KeyError on the advance_steps hot path.
            tracker_handle.clear_correction_resume_point()
            return
        current_step = getattr(frame, "step_id", None)
        reached = frame.frame_id == resume_frame_id and (
            current_step == resume_step_id if current_step is not None else True
        )
        frame_gone = resume_frame_id not in self._stack_path_frame_ids(tracker_handle)
        if reached or frame_gone:
            tracker_handle.clear_correction_resume_point()

    @staticmethod
    def _stack_path_frame_ids(tracker_handle: "TrackerHandle") -> set[str]:
        """Return frame ids for live skill/block frames and any leftover user-flow."""
        return {
            frame.frame_id
            for frame in (
                *tracker_handle.skill_and_block_frames(),
                *tracker_handle.user_flow_frames(),
            )
        }

    def _replay_after_correction(
        self,
        target: CorrectableMemoryItem,
        anchor_position: Optional[int],
        written_by_apply: set[str],
        tracker_handle: "TrackerHandle",
        resume_point: Optional[Tuple[str, str]] = None,
    ) -> None:
        """Rewind + clear-after-rewind so the corrected flow re-walks forward.

        Guided/hybrid only: reposition the owning frame to the corrected step,
        clear the stale derived state that frame produced after the rewind
        anchor, and let the next ``advance_steps`` re-walk — re-asking cleared
        collects and **re-confirming** at confirmation gates. Autonomous frames
        are handed back to the LLM unchanged (the value is already applied); the
        LLM re-derives the remaining state conversationally.

        *written_by_apply* are the slots the producer re-invoke just wrote (the
        corrected value plus any side effects it recomputes, e.g. a shipping
        summary or confirmation flag). They land after the anchor but are the
        fresh, corrected output, so they are preserved rather than cleared —
        mirroring the re-entry path.
        """
        if target.frame_id not in self._stack_path_frame_ids(tracker_handle):
            return
        resolved_target = self._skill_catalog.resolve_activation_target(target.flow_id)
        if resolved_target is None or is_autonomous_skill(
            resolved_target, self._skill_catalog
        ):
            return

        events: List[Event] = []
        if anchor_position is not None:
            keep_slots = {target.memory_key} | written_by_apply
            events.extend(
                create_memory_write_event(slot)
                for slot in slots_to_clear_after_rewind(
                    tracker_handle,
                    anchor_position,
                    {target.frame_id},
                    keep_slots,
                )
            )

        new_stack = build_rewound_stack(tracker_handle, target.frame_id, target.step_id)
        if new_stack is not None:
            events.extend(tracker_handle.create_stack_update_events(new_stack))

        if events:
            structlogger.debug(
                "mantle.skill_executor.dispatch.correct.rewind",
                frame_id=target.frame_id,
                step_id=target.step_id,
                event_count=len(events),
            )
            tracker_handle.apply_events(events)
            if resume_point is not None and any(
                is_memory_write_event(event) for event in events
            ):
                tracker_handle.set_correction_resume_point(*resume_point)

    def _replay_reentry(
        self,
        target: CorrectableMemoryItem,
        anchor_position: Optional[int],
        written_by_apply: set[str],
        tracker_handle: "TrackerHandle",
        resume_point: Optional[Tuple[str, str]] = None,
    ) -> None:
        """Re-enter a completed sub-skill so the corrected value drives again.

        Cross-skill path: reconstruct the stack from history so the popped
        sub-skill frame is live again at its owning collect step (and its
        ancestor is rewound to the call-return step), then clear the now-stale
        downstream state produced by the rewound chain after the correction
        anchor. The next ``advance_steps`` re-walks — the re-asked collect skips
        because the value is already corrected, the sub-skill completes, and the
        ancestor recomputes eligibility / derived state for the new value.

        *written_by_apply* are the slots the producer re-invoke just wrote; they
        are preserved even though they land after the anchor.
        """
        new_stack = reconstruct_stack_for_reentry(
            tracker_handle, target.frame_id, target.step_id
        )
        if new_stack is None:
            return

        # The rewound chain is every frame in the reconstructed stack: the
        # re-entered sub-skill plus the ancestor(s) repositioned to their
        # call-return step. State they produced after the anchor is stale.
        chain = {
            frame.frame_id
            for frame in new_stack.frames
            if getattr(frame, "frame_id", None) is not None
        }

        events: List[Event] = []
        if anchor_position is not None:
            keep_slots = {target.memory_key} | written_by_apply
            events.extend(
                create_memory_write_event(slot)
                for slot in slots_to_clear_after_rewind(
                    tracker_handle, anchor_position, chain, keep_slots
                )
            )

        events.extend(tracker_handle.create_stack_update_events(new_stack))

        if events:
            structlogger.debug(
                "mantle.skill_executor.dispatch.correct.reentry",
                frame_id=target.frame_id,
                step_id=target.step_id,
                chain=sorted(chain),
                cleared=[
                    event.key for event in events if isinstance(event, MemoryCleared)
                ],
                event_count=len(events),
            )
            tracker_handle.apply_events(events)
            if resume_point is not None and any(
                is_memory_write_event(event) for event in events
            ):
                tracker_handle.set_correction_resume_point(*resume_point)
